// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";
import "./backend_client.js";

/* Chronexa Solver — Pre-launch dialog (Generate flow redesign).
 *
 * Moment 1 of 3 in the unified Generate flow: ASK.
 *   Ask (this dialog) → Work (progress_modal.js) → Land (result_panel.js)
 *
 * Redesign principles:
 *   - Preset-first: Fast preview / Balanced / Best result / Custom. The old
 *     Complexity + Conditions + Algorithm radios still exist with the same
 *     input names, but live inside a collapsed "Advanced" section — Custom
 *     reveals them. School size auto-picks the preset.
 *   - One language: titles/counts use "placed / left to place" everywhere so
 *     Ask, Work and Land read as one flow.
 *   - Class-name contract (do not rename — e2e + solver_presets observer):
 *       .csu-modebtn[data-mode] + .is-selected, .chrx-preset-card,
 *       #csu-prelaunch-start, #csu-prelaunch-summary,
 *       input names complexity/conditions/algorithm.
 *
 * Public API (unchanged):
 *   SolverUI.PreLaunch.open(opts)
 *     opts.defaultMode : "generate" | "test" | "improve" | "best" (default "best")
 *     opts.school      : SchoolData (only used for the summary strip)
 *     opts.onConfirm(cfg), opts.onCancel()
 *   cfg = { mode, complexity, conditions, algorithm, showReport,
 *           timeLimitSec, warmStart?, useLNS?, improve? }
 */
(function (global) {
  "use strict";

  const TIME_LIMIT_BY_COMPLEXITY = { normal: 30, large: 60, huge: 120 };

  // Generator modes (guaranteed-safe generation modes)
  const GEN_MODES = [
    { id: "rebuild",      label: "Rebuild",           sub: "May move anything not locked", icon: "refresh" },
    { id: "improve_only", label: "Improve only",      sub: "Keep placed lessons; smooth out gaps and conflicts", icon: "sparkle" },
    { id: "add_unplaced", label: "Add unplaced only", sub: "Never move placed cards; fill free slots", icon: "lesson" },
  ];

  // Preset → underlying solver knobs. Conditions values must match the
  // Advanced radio values (draft / relax / strict).
  const PRESETS = [
    { id: "fast",     label: "Quick",    sub: "~30s · fast draft",      timeLimitSec: 30,  complexity: "normal", conditions: "draft",  icon: "clock" },
    { id: "balanced", label: "Balanced", sub: "~90s · good balance",    timeLimitSec: 90,  complexity: "large",  conditions: "relax",  icon: "layers", recommended: true },
    { id: "best",     label: "Best",     sub: "~5 min · thorough run",  timeLimitSec: 300, complexity: "huge",   conditions: "strict", icon: "sparkle" },
  ];

  function icNode(name, size) {
    return (global.ChrxIcons && typeof global.ChrxIcons.node === "function")
      ? global.ChrxIcons.node(name, size || 15)
      : "";
  }
  const PRESET_BY_COMPLEXITY = { normal: "fast", large: "balanced", huge: "best" };

  let host, dialog, current;

  function el(tag, attrs, ...kids) {
    const n = document.createElement(tag);
    if (attrs) for (const k in attrs) {
      if (k === "class") n.className = attrs[k];
      else if (k.startsWith("on") && typeof attrs[k] === "function") n.addEventListener(k.slice(2), attrs[k]);
      else n.setAttribute(k, attrs[k]);
    }
    for (const c of kids) if (c != null) n.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    return n;
  }

  function radioGroup(name, options, defaultValue) {
    const wrap = el("div", { class: "csu-radio-row", role: "radiogroup", "aria-label": name });
    for (const o of options) {
      const id = `csu-${name}-${o.value}`;
      const input = el("input", { type: "radio", name, id, value: o.value });
      if (o.value === defaultValue) input.checked = true;
      const lab = el("label", { class: "csu-radio", for: id },
        input,
        el("span", { class: "csu-radio__title" }, o.label),
        o.hint ? el("span", { class: "csu-radio__hint" }, o.hint) : null,
      );
      wrap.appendChild(lab);
    }
    return wrap;
  }

  function selectedRadio(wrap, name) {
    const r = wrap.querySelector(`input[name="${name}"]:checked`);
    return r ? r.value : null;
  }

  function modeButton(mode, icon, title, hint) {
    return el("button", {
      type: "button",
      class: "csu-modebtn",
      "data-mode": mode,
      onclick: () => setMode(mode),
    },
      el("span", { class: "csu-modebtn__icon" }, icon),
      el("span", { class: "csu-modebtn__title" }, title),
      el("span", { class: "csu-modebtn__hint" }, hint),
    );
  }

  function build() {
    host = el("div", { class: "csu-backdrop", role: "presentation", "aria-hidden": "true" });
    host.addEventListener("click", (e) => { if (e.target === host) doCancel(); });

    dialog = el("section", {
      class: "csu-dialog csu-prelaunch",
      role: "dialog",
      "aria-modal": "true",
      "aria-labelledby": "csu-prelaunch-title",
    });

    const titleEl = el("h2", { class: "csu-dialog__title", id: "csu-prelaunch-title" }, "Generate timetable");
    const sub = el("p", { class: "csu-dialog__sub" }, "One click builds the whole week. Pick a speed — the details stay automatic.");
    const summary = el("div", { class: "csu-dialog__summary", id: "csu-prelaunch-summary" }, "");

    // --- Mode: Best first (default), Test demoted to a quiet secondary ----
    const modeBtnBest = modeButton("best", icNode("sparkle", 16), "Best timetable", "Draft fast, then polish — one click, offline, toward 100%.");
    const modeBtnGen = modeButton("generate", icNode("play", 16), "Generate timetable", "Run the solver from scratch and place cards.");
    const modeBtnImp = modeButton("improve", icNode("refresh", 16), "Improve current schedule", "Keep placements and smooth out gaps and conflicts.");
    const modeBtnTest = modeButton("test", icNode("check", 16), "Test the timetable", "Validate constraints — does not move any card.");
    modeBtnTest.classList.add("csu-modebtn--quiet");
    const modeRow = el("div", { class: "csu-mode-row" }, modeBtnBest, modeBtnGen, modeBtnImp, modeBtnTest);

    // --- Generator Modes (guaranteed safe modes) ----------------------------
    const genModeGrid = el("div", { class: "chrx-genmode-grid", role: "radiogroup", "aria-label": "Generation mode" });
    for (const m of GEN_MODES) {
      const card = el("button", {
        type: "button",
        class: "chrx-genmode-card" + (m.id === "rebuild" ? " is-selected" : ""),
        "data-gen-mode": m.id,
        role: "radio",
        "aria-checked": m.id === "rebuild" ? "true" : "false",
        onclick: () => selectGeneratorMode(m.id),
      },
        el("div", { class: "chrx-genmode-label" }, m.icon ? icNode(m.icon, 14) : null, " ", m.label),
        el("div", { class: "chrx-genmode-sub" }, m.sub),
      );
      genModeGrid.appendChild(card);
    }
    const genModeStrip = el("div", { class: "chrx-genmode-strip", "data-native": "true" },
      el("p", { class: "chrx-preset-title" }, "Mode"),
      genModeGrid,
    );

    // --- Preset picker (native; same class names the old observer injected
    // so e2e locators and the observer guard keep working) ------------------
    const presetGrid = el("div", { class: "chrx-preset-grid", role: "radiogroup", "aria-label": "Speed" });
    for (const p of PRESETS) {
      const card = el("button", {
        type: "button",
        class: "chrx-preset-card" + (p.recommended ? " chrx-preset-card--recommended" : ""),
        "data-preset": p.id,
        role: "radio",
        "aria-checked": p.id === "balanced" ? "true" : "false",
        onclick: () => selectPreset(p.id),
      },
        el("div", { class: "chrx-preset-label" }, icNode(p.icon, 15), " ", p.label),
        el("div", { class: "chrx-preset-sub" }, p.sub),
      );
      if (p.recommended) card.appendChild(el("span", { class: "chrx-preset-badge" }, "Recommended"));
      presetGrid.appendChild(card);
    }
    const presetStrip = el("div", { class: "chrx-preset-strip", "data-native": "true" },
      el("p", { class: "chrx-preset-title" }, "Speed"),
      presetGrid,
    );

    // --- Advanced (collapsed): the old Complexity / Conditions / Algorithm --
    const complexity = radioGroup("complexity", [
      { value: "normal", label: "Normal", hint: "30s · small school" },
      { value: "large",  label: "Large",  hint: "60s · 30–50 classes" },
      { value: "huge",   label: "Huge",   hint: "2 min · 60+ teachers" },
    ], "large");
    const conditions = radioGroup("conditions", [
      { value: "draft",  label: "Draft",             hint: "Accept any partial result." },
      { value: "relax",  label: "Allow relaxation",  hint: "Skip the toughest soft constraints if stuck." },
      { value: "strict", label: "Strict",            hint: "Reject anything with hard conflicts." },
    ], "relax");
    const cloudReady = !!(global.CHRONEXA_BACKEND_URL && global.CHRONEXA_BACKEND_URL.length > 0);
    const algorithm = radioGroup("algorithm", [
      { value: "browser", label: "Run on this computer", hint: "Uses a Web Worker. Stays offline." },
      { value: "wasm",    label: "CP-SAT in browser",    hint: "Full OR-Tools portfolio · offline · multi-threaded." },
      { value: "cloud",   label: "Run on cloud",          hint: cloudReady ? "OR-Tools CP-SAT via backend." : "Backend URL not set — will fall back to browser." },
    ], "browser");
    // --- Report toggle -------------------------------------------------------
    const reportTog = el("input", { type: "checkbox", id: "csu-show-report" });
    reportTog.checked = true;
    const reportLabel = el("label", { class: "csu-toggle", for: "csu-show-report" },
      reportTog,
      el("span", null, "Show summary report after run"),
    );

    const advanced = el("details", { class: "csu-advanced", id: "csu-advanced" },
      el("summary", { class: "csu-advanced__toggle" }, "More options"),
      el("div", { class: "csu-advanced__body" },
        genModeStrip,
        sectionTitle("Action"),        modeRow,
        sectionTitle("Complexity"),    complexity,
        sectionTitle("Conditions"),    conditions,
        el("div", { id: "csu-algo-section" }, sectionTitle("Algorithm"), algorithm),
        reportLabel,
      ),
    );

    // --- Actions -------------------------------------------------------------
    const cancelBtn = el("button", { type: "button", class: "chrx-btn csu-btn--ghost", onclick: doCancel }, "Cancel");
    const startBtn  = el("button", { type: "button", class: "chrx-btn chrx-btn--primary", id: "csu-prelaunch-start", onclick: doStart }, "Build timetable");
    const footNote = el("p", { class: "csu-dialog__foot" }, "Stop any time to keep the best timetable found so far. Cancelling leaves your current timetable unchanged. Runs privately on your device.");
    const actions = el("div", { class: "csu-dialog__actions" }, cancelBtn, startBtn);

    dialog.append(titleEl, sub, summary, presetStrip, advanced, actions, footNote);
    dialog.dataset.preset = "balanced";
    dialog.dataset.generatorMode = "rebuild";
    host.appendChild(dialog);
    document.body.appendChild(host);

    host.addEventListener("keydown", (e) => {
      if (e.key === "Escape") { e.preventDefault(); doCancel(); }
    });
  }

  function sectionTitle(text) {
    return el("h3", { class: "csu-dialog__section" }, text);
  }

  function selectPreset(id) {
    if (!dialog) return;
    const preset = PRESETS.find(p => p.id === id) || PRESETS[1];
    dialog.dataset.preset = preset.id;
    if (preset.timeLimitSec) dialog.dataset.timeLimitSec = String(preset.timeLimitSec);
    else delete dialog.dataset.timeLimitSec;
    dialog.querySelectorAll(".chrx-preset-card").forEach(c => {
      const on = c.dataset.preset === preset.id;
      c.classList.toggle("is-selected", on);
      c.setAttribute("aria-checked", on ? "true" : "false");
    });
    if (!preset.custom) {
      const radios = dialog.querySelectorAll('input[type="radio"]');
      radios.forEach(r => {
        if (r.name === "complexity" && r.value === preset.complexity) r.checked = true;
        if (r.name === "conditions" && r.value === preset.conditions) r.checked = true;
      });
      dialog.querySelector("#csu-advanced").open = false;
    } else {
      dialog.querySelector("#csu-advanced").open = true;
    }
  }

  function selectGeneratorMode(id) {
    if (!dialog) return;
    const mode = GEN_MODES.find(m => m.id === id) || GEN_MODES[0];
    dialog.dataset.generatorMode = mode.id;
    dialog.querySelectorAll(".chrx-genmode-card").forEach(c => {
      const on = c.dataset.genMode === mode.id;
      c.classList.toggle("is-selected", on);
      c.setAttribute("aria-checked", on ? "true" : "false");
    });
    updateStartButton();
  }

  function updateStartButton() {
    if (!dialog) return;
    const startBtn = dialog.querySelector("#csu-prelaunch-start");
    if (!startBtn) return;
    const mode = dialog.dataset.mode || "best";
    const genMode = dialog.dataset.generatorMode || "rebuild";
    if (mode === "test") {
      startBtn.textContent = "Run test";
    } else if (genMode === "improve_only") {
      startBtn.textContent = "Improve";
    } else if (genMode === "add_unplaced") {
      startBtn.textContent = "Add unplaced cards";
    } else if (mode === "best") {
      startBtn.textContent = "Build timetable";
    } else {
      startBtn.textContent = "Build timetable";
    }
  }

  function setMode(mode) {
    if (!dialog) return;
    dialog.querySelectorAll(".csu-modebtn").forEach(b => {
      b.classList.toggle("is-selected", b.dataset.mode === mode);
    });
    // Test is validate-only: speed presets and mode strip don't apply.
    const genStrip = dialog.querySelector(".chrx-genmode-strip");
    if (genStrip) genStrip.style.display = mode === "test" ? "none" : "";
    const strip = dialog.querySelector(".chrx-preset-strip");
    if (strip) strip.style.display = mode === "test" ? "none" : "";
    // Algorithm/backend choice only applies to Generate and Improve.
    const algoSec = dialog.querySelector("#csu-algo-section");
    if (algoSec) algoSec.style.display = (mode === "generate" || mode === "improve") ? "" : "none";
    dialog.dataset.mode = mode;
    if (mode === "improve") {
      selectGeneratorMode("improve_only");
    }
    updateStartButton();
  }

  function setSummary(school) {
    const sum = dialog.querySelector("#csu-prelaunch-summary");
    if (!sum) return;
    if (!school) { sum.textContent = ""; sum.classList.remove("is-on"); return; }
    const c = (school._meta && school._meta.counts) || {};
    const teachers = (school.teachers && school.teachers.length) || c.teachers || 0;
    const classes  = (school.classes  && school.classes.length)  || c.classes  || 0;
    const expected = (global.SolverUI && typeof global.SolverUI.expectedCardCount === "function")
      ? global.SolverUI.expectedCardCount(school)
      : ((school.lessons && school.lessons.length) || c.lessons || 0);
    const cards    = (school.cards    && school.cards.length)    || c.cards    || 0;
    let conflicts = 0;
    try {
      if (global.Verifier && typeof global.Verifier.verify === "function") {
        conflicts = global.Verifier.verify(school).filter((v) => v && v.severity === "hard").length;
      }
    } catch (_) {}
    sum.innerHTML = "";
    const chip = (n, label) => {
      const s = el("span", { class: "csu-chip" },
        el("strong", {}, typeof n === "number" ? n.toLocaleString() : String(n)), document.createTextNode(" " + label));
      sum.appendChild(s);
    };
    const rawName = (school.schoolName || "").trim();
    const isPlaceholder = !rawName || /^(classic timetable|asc timetables|untitled|\(school\))/i.test(rawName);
    const displayName = isPlaceholder ? (school._isDemo ? "Sample school" : "My school") : rawName;
    const name = el("span", { class: "csu-chip csu-chip--name" }, displayName);
    sum.appendChild(name);
    chip(teachers, "teachers");
    chip(classes, "classes");
    chip(expected, "lesson periods to place");
    if (cards > 0) {
      const gridNote = conflicts > 0
        ? `currently on the grid, ${conflicts} ${conflicts === 1 ? "conflict" : "conflicts"}`
        : "currently on the grid";
      chip(cards, gridNote);
    }
    const RC = global.SolverUI && global.SolverUI.RunConditions;
    const off = RC ? RC.offCount(school) : 0;
    sum.appendChild(el("button", { type: "button", class: "csu-chip csu-chip--link" + (off ? " is-warn" : ""),
      id: "csu-run-conditions", title: "Switch condition families on or off for this run",
      onclick: () => RC && RC.open({ onClose: () => setSummary(school) }) },
      off ? `${off} condition famil${off === 1 ? "y" : "ies"} off` : "Conditions: all on"));
    sum.classList.add("is-on");
  }

  function doCancel() {
    close();
    if (current && current.onCancel) {
      try { current.onCancel(); } catch (e) { console.error(e); }
    }
    current = null;
  }

  function doStart() {
    const mode = dialog.dataset.mode || "best";
    const generatorMode = dialog.dataset.generatorMode || "rebuild";
    const preset = PRESETS.find(p => p.id === dialog.dataset.preset);
    const cfg = {
      mode,
      generatorMode,
      complexity: selectedRadio(dialog, "complexity") || "large",
      conditions: selectedRadio(dialog, "conditions") || "relax",
      algorithm:  selectedRadio(dialog, "algorithm")  || "browser",
      showReport: !!dialog.querySelector("#csu-show-report").checked,
    };
    // Explicit dataset timeLimitSec wins (for capped test runs); preset/complexity fallbacks.
    cfg.timeLimitSec = Number(dialog.dataset.timeLimitSec)
      || (preset && preset.timeLimitSec)
      || TIME_LIMIT_BY_COMPLEXITY[cfg.complexity]
      || 60;
    if (mode === "best") cfg.algorithm = "auto";
    if (mode === "improve" || generatorMode === "improve_only") {
      cfg.improve = true;
      cfg.improveOnly = true;
      cfg.warmStart = true;
      cfg.useLNS    = true;
    }
    if (generatorMode === "add_unplaced") {
      cfg.addUnplacedOnly = true;
      cfg.warmStart = true;
    }
    const cb = current && current.onConfirm;
    close();
    current = null;
    if (cb) {
      try { cb(cfg); } catch (e) { console.error(e); }
    }
  }

  /** Default run mode by size: tiny schools generate instantly, big ones polish. */
  function suggestDefaultMode(periodLoad) {
    const load = Number(periodLoad) || 0;
    return load > 0 && load <= 120 ? "generate" : "best";
  }

  function suggestComplexity(school) {
    if (!school) return null;
    const lessons  = (school.lessons  && school.lessons.length)  || 0;
    const teachers = (school.teachers && school.teachers.length) || 0;
    const classes  = (school.classes  && school.classes.length)  || 0;
    if (lessons > 200 || teachers > 50 || classes > 25) return "huge";
    if (lessons > 80  || teachers > 25 || classes > 12) return "large";
    return "normal";
  }
  function applySuggestedComplexity(school) {
    if (!dialog) return;
    const suggested = suggestComplexity(school);
    if (!suggested) return;
    const radios = dialog.querySelectorAll("input[name='complexity']");
    radios.forEach(r => { r.checked = (r.value === suggested); });
    // Mirror the suggestion into the preset picker AND move the Recommended badge
    // onto the preselected option so "Recommended" always matches what is selected.
    const chosenId = PRESET_BY_COMPLEXITY[suggested] || "balanced";
    selectPreset(chosenId);
    dialog.querySelectorAll(".chrx-preset-card").forEach(c => {
      const isRec = c.dataset.preset === chosenId;
      c.classList.toggle("chrx-preset-card--recommended", isRec);
      let badge = c.querySelector(".chrx-preset-badge");
      if (isRec && !badge) {
        c.appendChild(el("span", { class: "chrx-preset-badge" }, "Recommended"));
      } else if (!isRec && badge) {
        badge.remove();
      }
    });
  }

  function open(opts) {
    current = opts || {};
    if (!host) build();
    // A tiny school should not be offered a five-minute "Best" run first: 12
    // periods solve in about a second. Big schools keep the thorough default.
    const sch = current.school || (global.APP && global.APP.school) || null;
    const periodLoad = sch
      ? (sch.lessons || []).reduce((n, l) => n + (l.periodsPerWeek || 0), 0)
      : 0;
    const smallSchool = periodLoad > 0 && periodLoad <= 120;
    setMode(current.defaultMode || suggestDefaultMode(periodLoad));
    selectGeneratorMode(current.generatorMode || current.defaultGeneratorMode || (current.defaultMode === "improve" ? "improve_only" : "rebuild"));
    const targetSchool = current.school || (global.APP && global.APP.school) || null;
    setSummary(targetSchool);
    applySuggestedComplexity(targetSchool);
    host.classList.add("is-open");
    host.setAttribute("aria-hidden", "false");
    requestAnimationFrame(() => {
      const f = dialog.querySelector("#csu-prelaunch-start");
      if (f) f.focus();
    });
  }
  function close() {
    if (!host) return;
    host.classList.remove("is-open");
    host.setAttribute("aria-hidden", "true");
  }

  global.SolverUI = global.SolverUI || {};
  global.SolverUI.PreLaunch = { open, close, suggestDefaultMode };
})(typeof window !== "undefined" ? window : globalThis);
